const apicache = require('apicache');
const cache = apicache.options({ redisClient }).middleware;

// whole-page cache for anonymous GETs (memory by default, Redis when shared)
app.get('/docs/:slug', cache('5 minutes'), renderDocs);

// or header-driven: let the CDN hold the page
app.get('/guides/:slug', (req, res) => {
  res.set('Cache-Control', 'public, s-maxage=300, stale-while-revalidate=60');
  res.set('Vary', 'Accept-Encoding');
  res.send(renderGuide(req.params.slug));
});
